SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$LOA Table 5.5.3 All activities - height triggers (not applicable to Dwelling houses) / High density residential zone$q$, 'LEVEL_OF_ASSESSMENT', $q$All activities | Code assessment | Height | High density residential zone code Any other relevant code | If involving building work and: - is not on land identified with a height greater than 9 metres on the Building height overlay map; and - includes a Partial third storey; and - is no more than 9 metres Note: This height trigger does not apply to Dwelling houses, refer to Table 5.10.5 Dwelling house overlay. | Impact assessment | Height | City Plan including: Strategic framework High density residential zone code Any other relevant code | If involving building work and exceeds: - the height identified on the Building height overlay map; or - where not identified on the Building height overlay map, either: - 9 metres in height; or - a Partial third storey Note: This height trigger does not apply to Dwelling houses, refer to Table 5.10.5 Dwelling house overlay. Note: No change to the categories of development and assessment applies when identified with ‘HX’ on the Building height overlay map. | Density | No density impact assessment trigger applies$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/310/0/false/08-Sep-2026/false$q$, $q$Level: Code / Impact assessment. Conditions: Height triggers expressly do not apply to Dwelling houses (refer Table 5.10.5); no density impact trigger$q$, NULL);
