SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$LOA Table 5.5.18 All activities - height/density triggers (not applicable to Dwelling houses) / Limited development (constrained land) zone$q$, 'LEVEL_OF_ASSESSMENT', $q$All activities | Code assessment | Height | Limited development (constrained land) zone code Any other relevant code | If involving building work and: - is not on land identified with a height greater than 9 metres on the Building height overlay map; and - includes a Partial third storey; and - is no more than 9 metres Note: This height trigger does not apply to Dwelling houses, refer to Table 5.10.5 Dwelling house overlay. Note: No change to the categories of development and assessment applies to freestanding telecommunication towers. | Impact assessment | Height | City Plan including: Strategic framework Limited development (constrained land) zone code Any other relevant code | If involving building work and exceeds: - the height identified on the Building height overlay map; or - where not identified on the Building height overlay map, either: - 9 metres in height; or - a Partial third storey Note: This height trigger does not apply to Dwelling houses, refer to Table 5.10.5 Dwelling house overlay. Note: No change to the categories of development and assessment applies to freestanding telecommunication towers. | Impact assessment | Density | City Plan including: Strategic framework Limited development (constrained land) zone code Any other relevant code | For all uses other than: - Dwelling house; or - Caretaker’s accommodation if density exceeds one dwelling per lot$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/331/0/false/08-Sep-2026/false$q$, $q$Level: Code / Impact assessment. Conditions: Height triggers expressly do not apply to Dwelling houses (refer Table 5.10.5); density impact trigger excludes Dwelling house$q$, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$LOA Table 5.10.5 Dwelling house (MCU) - Dwelling house overlay / High density residential zone / Limited development (constrained land) zone, where on Dwelling house overlay map$q$, 'LEVEL_OF_ASSESSMENT', $q$Material change of use for Dwelling house where identified on the Dwelling house overlay map, if involving building work and: - is not on land identified with a height greater than 9 metres on the Building height overlay map; and - includes a Partial third storey; and - height is no more than 9 metres | Code assessment if provisionally made accepted or accepted subject to requirements by another table of assessment | Applicable zone code | Material change of use for Dwelling house where identified on the Dwelling house overlay map, if involving building work and exceeds: - the height identified on the Building height overlay map; or - where not identified on the Building height overlay map, either: - a Partial third storey; or - 9 metres in height | Impact assessment | City Plan including: Strategic framework Any other relevant code$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/290/0/false/08-Sep-2026/false$q$, $q$Level: Code assessment / Impact assessment. Conditions: Code assessment (applicable zone code) if partial third storey within 9m and not on land with height > 9m on Building height overlay map; Impact if exceeds Building height overlay map height or, where not identified, a Partial third storey or 9m$q$, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$LOA Table 1.5-1 Building work - QDC alternative provisions / High density residential zone / Limited development (constrained land) zone$q$, 'LEVEL_OF_ASSESSMENT', $q$Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA | Alternatives to QDC site cover provisions | Relevant zone code or the following overlay code: - Ridges and significant hills protection overlay code, if in the ‘Ridges and significant hills’ area on the Ridges and significant hills protection overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. | Section 33(2) BA | Alternative to QDC building height provisions (performance criterion 4) | Relevant zone code | Section 32(b) BA and section 10(2)(b) BR$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/63/0/false/08-Sep-2026/false$q$, $q$Level: Building assessment (Table 1.5-1). Conditions: Relevant zone code is the QDC alternative for boundary clearance (Buildings only) and site cover, and for QDC P4 building height; structures (e.g. pools) only via Coastal erosion hazard / Road widening overlay codes. Applies to HDR and LD zone codes alike (Table 1.5-1 is not zone-specific).$q$, NULL);
