SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.1.3 Table 6.2.1-1 RO3; Table 6.2.1-2 AO3.2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Structures do not exceed a height of 9m.$q$, 'VERIFIED_VERBATIM', $q$ruleId 364 / 392$q$, NULL, $q$Low density residential zone code (6.2.1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/37/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ldr_structure_height$q$);
