SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.2.3 Table 6.2.2-1 RO1 (small lots); Table 6.2.2-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Setbacks for Dwelling houses on small lots: | Setback | Minimum distances measured in metres (m) | Front | 4.5m to wall and balcony | Secondary frontage of corner lot | 4m (not including projections up to 2m) | Covered car parking (not applicable to the rear lane access) | 1m behind front wall or balcony; and 6m from the frontage where vehicles access the lot. | Side and rear (not applicable to the secondary frontage of corner lots) | Height | Setback | up to 4.5m | 1m to wall and balcony 0.5m to outermost projection 0m to class 10 building and/or non-habitable room where: - located along a southern or western boundary; - a maximum length of 12m where no single part exceeds 6m in length; and - at least 1m separation from a habitable window of a neighbouring dwelling. | for that part between 4.5m – 7.5m | 1.5m to wall and balcony 1m to outermost projection | for that part exceeding 7.5m | 2m to wall and balcony 1.5m to outermost projection | Rear lane | 0.5m maximum 1.0m maximum for covered car parking | OR For development on rear lots the setback is 3m from all boundaries.$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.2-1 RO1 (ruleId 16554); Table 6.2.2-2 AO1 (ruleId 16559)$q$, NULL, $q$Medium density residential zone code (6.2.2)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/36/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_mdr_small_lot_setbacks$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_mdr_small_lot_setbacks", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.FRONTAGE", "title": "6.2.2.3 Table 6.2.2-1 RO1 (small lots); Table 6.2.2-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "Setbacks for Dwelling houses on small lots: | Setback | Minimum distances measured in metres (m) | Front | 4.5m to wall and balcony | Secondary frontage of corner lot | 4m (not including projections up to 2m) | Covered car parking (not applicable to the rear lane access) | 1m behind front wall or balcony; and 6m from the frontage where vehicles access the lot. | Side and rear (not applicable to the secondary frontage of corner lots) | Height | Setback | up to 4.5m | 1m to wall and balcony 0.5m to outermost projection 0m to class 10 building and/or non-habitable room where: - located along a southern or western boundary; - a maximum length of 12m where no single part exceeds 6m in length; and - at least 1m separation from a habitable window of a neighbouring dwelling. | for that part between 4.5m – 7.5m | 1.5m to wall and balcony 1m to outermost projection | for that part exceeding 7.5m | 2m to wall and balcony 1.5m to outermost projection | Rear lane | 0.5m maximum 1.0m maximum for covered car parking | OR For development on rear lots the setback is 3m from all boundaries.", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_1"], "sources": [{"key": "gc_mdr_small_lot_setbacks", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"small_lot_setbacks\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"front 4.5m to wall and balcony\", \"secondary frontage 4m\", \"covered parking 1m behind front wall and 6m from vehicle-access frontage\", \"side/rear 1m/1.5m/2m to wall by height band; 0.5/1/1.5m to outermost projection\", \"rear lots 3m all boundaries\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): small lot (< 400m2)\nStructure scope 'Dwelling house on small lot' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Same as LDR small-lot table, except RO1 (Part A) reads 'Rear lane | 0.5m maximum 1.0m maximum for covered car parking' while AO1 (Part B) reads '0.5m minimum 1m maximum' - apparent drafting inconsistency. Table 1.5-1 (s1.5 Building work regulated under the City Plan) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_mdr_small_lot_setbacks@2026-09-29$q$;
