SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$Table 8.2.13 RO1 / AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Setbacks comply with the following: | Building type | Setback | Minimum distances measured in metres (m) | Mixed use and commercial buildings | Front | Equal to that used by more than 50% of the other buildings in the village and on the street OR 6m | Side and rear | 2m | Residential buildings and structures | Front | 3m | Side and rear | 1.5m$q$, 'VERIFIED_VERBATIM', $q$ruleId 16470 / 16492$q$, NULL, $q$Mudgeeraba Village character overlay code (8.2.13)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/42/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_mudgeeraba_residential_setbacks$q$);
