SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$RO1; AO1; Table 8.2.19-2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Development complies with the horizontal separation distances (setbacks) within Table 8.2.19-2: Minimum horizontal separation distances required in water resource catchment area.$q$, 'VERIFIED_VERBATIM', $q$Part A RO1 and Part B AO1 (ruleId near 4246)$q$, NULL, $q$Water resource catchment overlay code (8.2.19)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/39/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_water_catchment_separation$q$);
