SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$Table 8.2.8-1 RO2, RO3; Table 8.2.8-2 AO2.1, AO3.1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Building floor levels of habitable rooms must be at or above the height of the combined designated flood level and minimum freeboard derived from Table 8.2.8-6 – table to acceptable outcome AO2.1. | RO3 Building floor levels of garages and non-habitable rooms, constructed at approximately the same level as, and attached to, the main dwelling, must be at a height above the Designated Flood Level.$q$, 'VERIFIED_VERBATIM', $q$ruleId 39346 ff$q$, NULL, $q$Flood overlay code (8.2.8)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/1403/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_flood_floor_levels$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_flood_floor_levels", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "OTHER", "title": "Table 8.2.8-1 RO2, RO3; Table 8.2.8-2 AO2.1, AO3.1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": ">=", "value": {"op": "unencoded", "text": "habitable: DFL + freeboard (Table 8.2.8-6); attached garage/non-habitable: > DFL", "extracted_value": null, "extracted_operator": ">="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "OVERLAY", "overlay": "CGC:OV:FLOOD_OVERLAY_FLOOD_ASSESSMENT_REQUIRED_AREA"}], "subjects": ["CLASS_10A"], "sources": [{"key": "gc_flood_floor_levels", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"floor_level\", \"operator\": \">=\", \"value\": null, \"unit\": null, \"conditions\": [], \"exceptions\": [], \"formula_text\": \"habitable: DFL + freeboard (Table 8.2.8-6); attached garage/non-habitable: > DFL\"}\nStructure scope 'habitable rooms; attached garages and non-habitable rooms' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Not a setback/height/site cover alternative. Table 1.5-1 lists Flood overlay code under s32(a) BA / s13(1)(b) BR (natural hazard management area - flood design requirements). Detached Class 10a not addressed in RO3."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_flood_floor_levels@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.20.3 Table 6.2.20-1 RO1; Table 6.2.20-2 PO1/AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | - if roadside stall: 0m - otherwise: 10m | Side and rear | 6m || Part B: PO1 Setbacks: - protect the amenity of adjacent uses; and - provide a level of privacy expected in a rural setting. | AO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | - if roadside stall: 0m - otherwise: 10m | Side and rear | 6m$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.20-1 (Part A, ruleId 1998) and Table 6.2.20-2 (Part B, ruleId 2007)$q$, NULL, $q$Rural zone code (6.2.20)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/18/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_rural_front_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_rural_front_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.FRONTAGE", "title": "6.2.20.3 Table 6.2.20-1 RO1; Table 6.2.20-2 PO1/AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 10, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_rural_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_setback_min\", \"operator\": \">=\", \"value\": 10, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [\"roadside stall: 0m\"], \"formula_text\": null}\nStructure scope 'all buildings assessed against the zone code (no Class 10 / outbuilding distinction); roadside stall 0m' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: RO1 (accepted subject to requirements) and AO1 (assessable) have identical setback tables. No secondary-frontage rule: Sch 1 'Frontage' = 'The boundary between a site and a road' (corner lots - see open questions). Dwelling house n.e.i MCU is Accepted in this zone (Table 5.5.20) with only overlay codes as requirements, so this setback reaches a dwelling house / Class 10a only as a QDC alternative provision via Table 1.5-1 (building work). No site cover provision exists in the Rural zone code. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
