SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.20.3 Table 6.2.20-1 RO2; Table 6.2.20-2 PO2/AO2.1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO2 Building height does not exceed 2 storeys with a maximum height of 9m. AND For structures, no requirements for accepted development are provided. || Part B: PO2 Building height is low rise. | AO2.1 Building height does not exceed: - 2 storeys with a maximum height of 9m; or - a partial third storey if within 9m. AO2.2 For structures, no acceptable outcome provided.$q$, 'VERIFIED_VERBATIM', $q$ruleId 1999 / 2010$q$, NULL, $q$Rural zone code (6.2.20)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/18/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Building height': vertical distance between ground level and the highest point on the roof (excluding aerial, chimney, flagpole, load-bearing antenna) or number of storeys above ground level. 'Partial third storey': GFA no greater than 50% of the storey immediately below.$q$, $q$gc_rural_building_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_rural_building_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "HEIGHT.BUILDING", "title": "6.2.20.3 Table 6.2.20-1 RO2; Table 6.2.20-2 PO2/AO2.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 9, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:RURAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "gc_rural_building_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"building_height_max\", \"operator\": \"<=\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"and not more than 2 storeys\", \"Part B AO2.1 alternatively allows 'a partial third storey if within 9m' (RO2 for accepted development does not)\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'buildings (incl. dwelling house and Class 10a buildings); structures excluded - see gc_rural_structure_height' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Table 1.5-1 (ruleId 2205): 'Alternative to QDC building height provisions (performance criterion 4) | Relevant zone code | Section 32(b) BA and section 10(2)(b) BR'. No separate height limit for freestanding garages/carports/sheds (unlike LDR/MDR 3.5m). The Rural MCU table height trigger (9m, other than class 10 buildings and structures) expressly does not apply to Dwelling houses (refer Table 5.10.5 Dwelling house overlay)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_rural_building_height@2026-09-29$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_rural_building_height@2026-09-29$q$, $q$QDC12.A4.BUILDING_HEIGHT$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_rural_building_height@2026-09-29$q$, $q$QDC11.A4.BUILDING_HEIGHT$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.20.3 Table 6.2.20-1 RO2; Table 6.2.20-2 AO2.2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO2 Building height does not exceed 2 storeys with a maximum height of 9m. AND For structures, no requirements for accepted development are provided. || Part B: PO2 Building height is low rise. | AO2.1 Building height does not exceed: - 2 storeys with a maximum height of 9m; or - a partial third storey if within 9m. AO2.2 For structures, no acceptable outcome provided.$q$, 'VERIFIED_VERBATIM', $q$ruleId 1999 / 2010$q$, NULL, $q$Rural zone code (6.2.20)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/18/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Building height': vertical distance between ground level and the highest point on the roof (excluding aerial, chimney, flagpole, load-bearing antenna) or number of storeys above ground level. 'Partial third storey': GFA no greater than 50% of the storey immediately below.$q$, $q$gc_rural_structure_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_rural_structure_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "HEIGHT.BUILDING", "title": "6.2.20.3 Table 6.2.20-1 RO2; Table 6.2.20-2 AO2.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "RO2 Building height does not exceed 2 storeys with a maximum height of 9m. AND For structures, no requirements for accepted development are provided. || Part B: PO2 Building height is low rise. | AO2.1 Building height does not exceed: - 2 storeys with a maximum height of 9m; or - a partial third storey if within 9m. AO2.2 For structures, no acceptable outcome provided.", "extracted_value": null, "extracted_operator": null}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:RURAL"}], "subjects": ["POOL"], "sources": [{"key": "gc_rural_structure_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"structure_height_max\", \"operator\": null, \"value\": null, \"unit\": \"m\", \"conditions\": [\"no numeric limit for structures in the Rural zone code\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'structures (non-building structures, e.g. pools, masts)' mapped by keyword to ['POOL']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: Structures have no numeric height limit in the Rural zone ('For structures, no requirements for accepted development are provided.' / 'For structures, no acceptable outcome provided.'). Whether a Class 10a shed/garage/carport is a 'building' (9m/2 storeys) or a 'structure' (no limit) - treated as a building here. Assessable development would be assessed against PO2 'Building height is low rise.'"}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_rural_structure_height@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.20.3 Table 6.2.20-1 RO4; Table 6.2.20-2 PO4/AO4$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO4 Buildings and structures do not protrude above ridgelines when viewed from any street. || Part B: PO4 Buildings are integrated within the landscape and do not appear as a prominent feature. | AO4 Buildings and structures do not protrude above ridgelines when viewed from any street.$q$, 'VERIFIED_VERBATIM', $q$ruleId 2001 / 2014$q$, NULL, $q$Rural zone code (6.2.20)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/18/0/false/08-Sep-2026/false$q$, NULL, $q$gc_rural_ridgeline$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_rural_ridgeline", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "OTHER", "title": "6.2.20.3 Table 6.2.20-1 RO4; Table 6.2.20-2 PO4/AO4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "=", "value": {"op": "unencoded", "text": "RO4 Buildings and structures do not protrude above ridgelines when viewed from any street. || Part B: PO4 Buildings are integrated within the landscape and do not appear as a prominent feature. | AO4 Buildings and structures do not protrude above ridgelines when viewed from any street.", "extracted_value": false, "extracted_operator": "=="}, "unit": null, "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_rural_ridgeline", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"protrude_above_ridgeline_viewed_from_street\", \"operator\": \"==\", \"value\": false, \"unit\": null, \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'buildings and structures' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Qualitative siting rule, not one of the Table 1.5-1 QDC alternative categories. Binds a dwelling house only where the Rural zone code is a requirement/benchmark (secondary dwelling cases, code/impact assessment); not a requirement for an accepted Dwelling house n.e.i. Not machine-checkable without terrain/viewshed data."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_rural_ridgeline@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.20.3 Table 6.2.20-1 RO3; Table 6.2.20-2 PO3/AO3$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO3 Residential density is limited to a dwelling house. || Part B: PO3 Residential density is limited to a dwelling house. | AO3 No acceptable outcome provided.$q$, 'VERIFIED_VERBATIM', $q$ruleId 2000 / 2012$q$, NULL, $q$Rural zone code (6.2.20)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/18/0/false/08-Sep-2026/false$q$, NULL, $q$gc_rural_density$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_rural_density", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "OTHER", "title": "6.2.20.3 Table 6.2.20-1 RO3; Table 6.2.20-2 PO3/AO3", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "<=", "value": 1, "unit": "dwelling house", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:RURAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_rural_density", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"dwelling_houses_per_lot\", \"operator\": \"<=\", \"value\": 1, \"unit\": \"dwelling house\", \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'residential use' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Context only (not a siting number). Secondary dwellings handled via Secondary dwelling code per Table 5.5.20."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_rural_density@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$1.5 Table 1.5-1 (Alternatives to QDC boundary clearance provisions)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA$q$, 'VERIFIED_VERBATIM', $q$Table 1.5-1, ruleId 2203$q$, NULL, $q$Section 1.5 Building work regulated under the City Plan (Part 1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/63/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_rural_pool_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_rural_pool_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "POOL.SETBACK", "title": "1.5 Table 1.5-1 (Alternatives to QDC boundary clearance provisions)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_POOL_SETBACK", "operator": ">=", "value": {"op": "unencoded", "text": "Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA", "extracted_value": null, "extracted_operator": null}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:RURAL"}], "subjects": ["POOL"], "sources": [{"key": "gc_rural_pool_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"pool_setback_min\", \"operator\": null, \"value\": null, \"unit\": \"m\", \"conditions\": [\"no Rural zone code pool setback; QDC/QHC setbacks apply unless in a Coastal erosion hazard 'Waterfront development control area'/'Foreshore seawall' area or a Road widening requirement area\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'swimming pools and other non-building structures' mapped by keyword to ['POOL']\nAlternative provision to QDC/QHC: NO\nResearcher notes: The Rural zone code contains no reference to swimming pools, sheds, garages, carports, outbuildings or Class 10 (text search of all rules in section 18). Under Table 1.5-1 the zone code is an alternative only for 'Buildings'; for 'Structures' only Coastal erosion hazard and Road widening overlay codes are alternatives. Pool = 'structure' classification is assumed - manual review."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_rural_pool_setback@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO1; Table 6.2.15-2 PO1/AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | 10m | Side and rear | 6m || Part B: PO1 Setbacks: - assist in the protection of adjacent amenity; - provide a level of privacy expected in the locality: - allow for access around the building; - contribute to the desired streetscape character for the locality; and - allow for on-site car parking. | AO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | 10m | Side and rear | 6m$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.15-1 (Part A, ruleId 13084) and Table 6.2.15-2 (Part B, ruleId 13143)$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ec_front_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_front_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.FRONTAGE", "title": "6.2.15.3 Table 6.2.15-1 RO1; Table 6.2.15-2 PO1/AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 10, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["ANY"], "sources": [{"key": "gc_ec_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_setback_min\", \"operator\": \">=\", \"value\": 10, \"unit\": \"m\", \"conditions\": [\"applies unless the Dwelling house is on a lot created through a residential subdivision approval\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): lot NOT created through a residential subdivision approval (general/interim case; no lot-area threshold stated)\nStructure scope 'all buildings (no Class 10 / outbuilding distinction)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Dwelling house (not involving a secondary dwelling) MCU is Accepted in this zone (Table 5.5.15) with only overlay codes as requirements, so this setback reaches a dwelling house / Class 10a only as a QDC alternative provision via Table 1.5-1. No secondary-frontage rule. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ec_front_setback@2026-09-29$q$;
