SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO1; Table 6.2.15-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | 10m | Side and rear | 6m || Part B: AO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | 10m | Side and rear | 6m$q$, 'VERIFIED_VERBATIM', $q$ruleId 13084 / 13143$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ec_side_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_side_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.SIDE", "title": "6.2.15.3 Table 6.2.15-1 RO1; Table 6.2.15-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["ANY"], "sources": [{"key": "gc_ec_side_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"side_setback_min\", \"operator\": \">=\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"lot not created through a residential subdivision approval\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): lot NOT created through a residential subdivision approval (general/interim case; no lot-area threshold stated)\nStructure scope 'all buildings' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: 'Side and rear' 6m, not height-dependent. No built-to-boundary/Class 10 allowance. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
