SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO1; Table 6.2.15-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | 10m | Side and rear | 6m || Part B: AO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | 10m | Side and rear | 6m$q$, 'VERIFIED_VERBATIM', $q$ruleId 13084 / 13143$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ec_rear_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_rear_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.REAR", "title": "6.2.15.3 Table 6.2.15-1 RO1; Table 6.2.15-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["ANY"], "sources": [{"key": "gc_ec_rear_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"rear_setback_min\", \"operator\": \">=\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"lot not created through a residential subdivision approval\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): lot NOT created through a residential subdivision approval (general/interim case; no lot-area threshold stated)\nStructure scope 'all buildings' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: 'Side and rear' 6m. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ec_rear_setback@2026-09-29$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ec_rear_setback@2026-09-29$q$, $q$QDC12.A2a.SIDE_REAR_CLEARANCE$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ec_rear_setback@2026-09-29$q$, $q$QDC11.A2a.SIDE_REAR_CLEARANCE$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO1 (second table); Table 6.2.15-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$OR For a Dwelling house on a lot created through a residential subdivision approval, the setbacks are as follows, unless the earlier approval specifies otherwise: | Setback | Minimum distances measured in metres (m) | Front | 6m | Side and rear | Height | Setback | up to 4.5m | 1.5m | between 4.5m – 7.5m | 2m | exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m || Part B: OR For a Dwelling house on a lot created through a residential subdivision approval, the setbacks are as follows, unless the earlier approval specifies otherwise: | Setback | Minimum distances measured in metres (m) | Front | 6m | Side and rear | Height | Setback | up to 4.5 | 1.5m | between 4.5m – 7.5m | 2m | exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m$q$, 'VERIFIED_VERBATIM', $q$ruleId 13084 / 13143$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ec_subdiv_lot_front_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_subdiv_lot_front_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.FRONTAGE", "title": "6.2.15.3 Table 6.2.15-1 RO1 (second table); Table 6.2.15-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "gc_ec_subdiv_lot_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_setback_min\", \"operator\": \">=\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"Dwelling house on a lot created through a residential subdivision approval\"], \"exceptions\": [\"unless the earlier approval specifies otherwise\"], \"formula_text\": null}\nLot conditions (not encoded): 'For a Dwelling house on a lot created through a residential subdivision approval' ... 'unless the earlier approval specifies otherwise' (no lot-area threshold)\nStructure scope 'Dwelling house (and its Class 10a buildings) on a lot created through a residential subdivision approval' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Whether a lot was 'created through a residential subdivision approval' (and whether that approval specifies other setbacks) cannot be determined from zoning data - needs approval / plan-of-development lookup. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ec_subdiv_lot_front_setback@2026-09-29$q$;
