SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO1 (second table); Table 6.2.15-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$OR For a Dwelling house on a lot created through a residential subdivision approval, the setbacks are as follows, unless the earlier approval specifies otherwise: | Setback | Minimum distances measured in metres (m) | Front | 6m | Side and rear | Height | Setback | up to 4.5m | 1.5m | between 4.5m – 7.5m | 2m | exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m || Part B: OR For a Dwelling house on a lot created through a residential subdivision approval, the setbacks are as follows, unless the earlier approval specifies otherwise: | Setback | Minimum distances measured in metres (m) | Front | 6m | Side and rear | Height | Setback | up to 4.5 | 1.5m | between 4.5m – 7.5m | 2m | exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m$q$, 'VERIFIED_VERBATIM', $q$ruleId 13084 / 13143$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ec_subdiv_lot_side_setback_height_tiered$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_subdiv_lot_side_setback_height_tiered", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.SIDE", "title": "6.2.15.3 Table 6.2.15-1 RO1 (second table); Table 6.2.15-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": 1.5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "gc_ec_subdiv_lot_side_setback_height_tiered", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"side_setback_min\", \"operator\": \">=\", \"value\": 1.5, \"unit\": \"m\", \"conditions\": [\"height up to 4.5m: 1.5m\", \"height between 4.5m and 7.5m: 2m\", \"height exceeding 7.5m: an extra 0.5m for every 3m in height or part thereof over 7.5m\"], \"exceptions\": [\"unless the earlier approval specifies otherwise\"], \"formula_text\": \"setback = 1.5m where height up to 4.5m; 2m where height between 4.5m and 7.5m; above 7.5m add 0.5m for every 3m (or part) of height over 7.5m, i.e. 2 + 0.5*ceil((h-7.5)/3)\"}\nLot conditions (not encoded): 'For a Dwelling house on a lot created through a residential subdivision approval' ... 'unless the earlier approval specifies otherwise' (no lot-area threshold)\nStructure scope 'Dwelling house (and its Class 10a buildings) on a lot created through a residential subdivision approval' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Part B AO1 reads 'up to 4.5' (no unit) where RO1 reads 'up to 4.5m' - typographical. Same tiers as the LDR standard table but WITHOUT the LDR 'Between on-site habitable buildings' separation row and without any small-lot / Class 10 built-to-boundary allowance. Whether 'Height' means overall building height or height of the relevant part is not stated (same issue as LDR). Subdivision-approval status needs a lookup. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ec_subdiv_lot_side_setback_height_tiered@2026-09-29$q$;
