INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ec_site_cover@2026-09-29$q$, $q$QDC11.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO2; Table 6.2.15-2 PO2/AO2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO2 Site cover does not exceed 5%. OR For a Dwelling house on a lot created through a residential subdivision approval, the site cover does not exceed 50%, unless the earlier approval specifies otherwise. || Part B: PO2 Site cover: - for interim activities: - limits the built form to protect the future urban development potential of the land; - maintains the low intensity character; and - provides areas for on-site sewerage facilities; or - for a Dwelling house created by a residential subdivision approval: - is balanced between built form and green areas for landscaped private open space; and - contributes towards neighbourhood character. Note: Interim activities comprise of low intensity activities such as Dwelling houses, Community residences, Home based businesses and Caretakers accommodation which do not compromise the future urban development potential of the land for new communities. | AO2 Site cover does not exceed 5%. OR For a Dwelling house on a lot created through a residential subdivision approval, the site cover does not exceed 50%, unless the earlier approval specifies otherwise.$q$, 'VERIFIED_VERBATIM', $q$ruleId 13085 / 13147$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Site cover': portion of the site (%) covered by a building or structure measured to its outermost projection, excluding gazebos/shade structures in landscaped or open space areas, basements completely below ground used for car parking, eaves, sun shades.$q$, $q$gc_ec_subdiv_lot_site_cover$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_subdiv_lot_site_cover", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SITE_COVER", "title": "6.2.15.3 Table 6.2.15-1 RO2; Table 6.2.15-2 PO2/AO2", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": 50, "unit": "%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["CLASS_1"], "sources": [{"key": "gc_ec_subdiv_lot_site_cover", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"site_cover_max_pct\", \"operator\": \"<=\", \"value\": 50, \"unit\": \"%\", \"conditions\": [\"Dwelling house on a lot created through a residential subdivision approval\"], \"exceptions\": [\"unless the earlier approval specifies otherwise\"], \"formula_text\": null}\nLot conditions (not encoded): 'For a Dwelling house on a lot created through a residential subdivision approval' ... 'unless the earlier approval specifies otherwise' (no lot-area threshold)\nStructure scope 'Dwelling house on a lot created through a residential subdivision approval' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: PO2 says 'a Dwelling house created by a residential subdivision approval' while RO2/AO2 say 'on a lot created through a residential subdivision approval'. Subdivision-approval status needs a lookup. Table 1.5-1 (ruleId 2204): 'Alternatives to QDC site cover provisions | Relevant zone code or the following overlay code: Ridges and significant hills protection overlay code ...' (Section 33(2) BA)."}$q$::jsonb);
