INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ec_subdiv_lot_site_cover@2026-09-29$q$, $q$QDC11.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO3; Table 6.2.15-2 PO3/AO3.1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO3 Building height does not exceed 2 storeys and a maximum of 9m or that shown on the Building height overlay map. and Structures do not exceed a height of 9m or that shown on the Building height overlay map. || Part B: PO3 Building height and structure height is low rise. | AO3.1 Building height does not exceed that shown on the Building height overlay map. OR Where not identified on the overlay map building height does not exceed: - 2 storeys with a maximum of 9m; or - a partial third storey if within 9m. AO3.2 Structures do not exceed a height of 9m or that shown on the Building height overlay map.$q$, 'VERIFIED_VERBATIM', $q$ruleId 13086 / 13249$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Building height': vertical distance between ground level and the highest point on the roof (excluding aerial, chimney, flagpole, load-bearing antenna) or number of storeys above ground level. 'Partial third storey': GFA no greater than 50% of the storey immediately below.$q$, $q$gc_ec_building_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_building_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "HEIGHT.BUILDING", "title": "6.2.15.3 Table 6.2.15-1 RO3; Table 6.2.15-2 PO3/AO3.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 9, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "gc_ec_building_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"building_height_max\", \"operator\": \"<=\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"and not more than 2 storeys\", \"or the height shown on the Building height overlay map\", \"Part B AO3.1 also allows 'a partial third storey if within 9m' where not identified on the overlay map\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'buildings (incl. dwelling house and Class 10a buildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Table 1.5-1 (ruleId 2205): 'Alternative to QDC building height provisions (performance criterion 4) | Relevant zone code | Section 32(b) BA and section 10(2)(b) BR'. Building height overlay map may set a different value (spatial lookup needed). RO3 reads '2 storeys and a maximum of 9m or that shown on the Building height overlay map' - ambiguous whether an overlay value replaces both limits. No separate freestanding garage/carport height limit."}$q$::jsonb);
