SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO3; Table 6.2.15-2 AO3.2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO3 Building height does not exceed 2 storeys and a maximum of 9m or that shown on the Building height overlay map. and Structures do not exceed a height of 9m or that shown on the Building height overlay map. || Part B: PO3 Building height and structure height is low rise. | AO3.1 Building height does not exceed that shown on the Building height overlay map. OR Where not identified on the overlay map building height does not exceed: - 2 storeys with a maximum of 9m; or - a partial third storey if within 9m. AO3.2 Structures do not exceed a height of 9m or that shown on the Building height overlay map.$q$, 'VERIFIED_VERBATIM', $q$ruleId 13086 / 13249$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Building height': vertical distance between ground level and the highest point on the roof (excluding aerial, chimney, flagpole, load-bearing antenna) or number of storeys above ground level. 'Partial third storey': GFA no greater than 50% of the storey immediately below.$q$, $q$gc_ec_structure_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_structure_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "HEIGHT.BUILDING", "title": "6.2.15.3 Table 6.2.15-1 RO3; Table 6.2.15-2 AO3.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 9, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["ANY"], "sources": [{"key": "gc_ec_structure_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"structure_height_max\", \"operator\": \"<=\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"or that shown on the Building height overlay map\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'structures' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: Table 1.5-1 names the zone code as alternative to QDC 'building height provisions (performance criterion 4)'; unclear whether this reaches non-building structures. Only binds as a planning requirement where the zone code is a requirement/benchmark."}$q$::jsonb);
