SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.15.3 Table 6.2.15-1 RO4; Table 6.2.15-2 PO4/AO4$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO4 Density is one dwelling house per lot. || Part B: PO4 Density is very low and promotes the intended intensity of the zone until detailed studies inform alternative density capacities for new communities. | AO4 Density is one dwelling house per lot.$q$, 'VERIFIED_VERBATIM', $q$ruleId 13087 / 13252$q$, NULL, $q$Emerging community zone code (6.2.15)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/23/0/false/08-Sep-2026/false$q$, NULL, $q$gc_ec_density$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_density", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "OTHER", "title": "6.2.15.3 Table 6.2.15-1 RO4; Table 6.2.15-2 PO4/AO4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "<=", "value": 1, "unit": "dwelling house", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["ANY"], "sources": [{"key": "gc_ec_density", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"dwelling_houses_per_lot\", \"operator\": \"<=\", \"value\": 1, \"unit\": \"dwelling house\", \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'residential use' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Context only."}$q$::jsonb);
