SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$1.5 Table 1.5-1 (Alternatives to QDC boundary clearance provisions)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA$q$, 'VERIFIED_VERBATIM', $q$Table 1.5-1, ruleId 2203$q$, NULL, $q$Section 1.5 Building work regulated under the City Plan (Part 1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/63/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ec_pool_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ec_pool_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "POOL.SETBACK", "title": "1.5 Table 1.5-1 (Alternatives to QDC boundary clearance provisions)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_POOL_SETBACK", "operator": ">=", "value": {"op": "unencoded", "text": "Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA", "extracted_value": null, "extracted_operator": null}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:EMERGING_COMMUNITY"}], "subjects": ["POOL"], "sources": [{"key": "gc_ec_pool_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"pool_setback_min\", \"operator\": null, \"value\": null, \"unit\": \"m\", \"conditions\": [\"no Emerging community zone code pool setback; QDC/QHC setbacks apply unless in a Coastal erosion hazard 'Waterfront development control area'/'Foreshore seawall' area or a Road widening requirement area\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'swimming pools and other non-building structures' mapped by keyword to ['POOL']\nAlternative provision to QDC/QHC: NO\nResearcher notes: The Emerging community zone code contains no reference to swimming pools, sheds, garages, carports, outbuildings or Class 10 (text search of all rules in section 23). Pool = 'structure' classification is assumed - manual review."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ec_pool_setback@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.3.3 Table 6.2.3-1 RO1; Table 6.2.3-2 PO1/AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Height | Setback | Front for covered car parking (excluding a basement) | all | 6m | Front (excluding covered car parking) | up to 23m | 4m | for that part exceeding 23m | 6m | Side and rear | up to 4.5m | 1.5m | for that part between 4.5m – 7.5m | 2m | for that part exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m | Between on site habitable buildings (where not attached) | Double the applicable side setback. | OR || Part B: AO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Height | Setback | Front for covered car parking (excluding a basement) | all | 6m | Front (excluding covered car parking) | up to 23m | 4m | for that part exceeding 23m | 6m | Side and rear | up to 4.5m | 1.5m | for that part between 4.5m – 7.5m | 2m | for that part exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m. | Between on site habitable buildings (where not attached) | Double the applicable side setback. | OR$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.3-1 (Part A, ruleId 469) and Table 6.2.3-2 (Part B, ruleId 490)$q$, NULL, $q$High density residential zone code (6.2.3)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/35/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_hdr_front_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_front_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.FRONTAGE", "title": "6.2.3.3 Table 6.2.3-1 RO1; Table 6.2.3-2 PO1/AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "part of building h<=23m -> 4m; part h>23m -> 6m", "extracted_value": 4, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_hdr_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_setback_min\", \"operator\": \"conditional\", \"value\": 4, \"unit\": \"m\", \"conditions\": [\"height up to 23m: 4m\", \"for that part exceeding 23m: 6m\", \"covered car parking (excluding a basement): 6m - see gc_hdr_front_setback_covered_parking\"], \"exceptions\": [\"Dwelling houses on small lots: 4.5m to wall and balcony (gc_hdr_small_lot_front_setback)\"], \"formula_text\": \"part of building h<=23m -> 4m; part h>23m -> 6m\"}\nLot conditions (not encoded): Standard (non-small-lot) table; small lot = lot area < 400m2 (Sch 1 'Small lot') may use the alternative 'Dwelling houses on small lots' table\nStructure scope 'all buildings other than covered car parking (zone code setback table; no Class 10 distinction)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: RO1 (accepted subject to requirements) and AO1 (assessable) standard tables are identical except AO1 ends the 7.5m row with a full stop. Unlike LDR (6m), HDR front setback for buildings is 4m up to 23m height. No rear-lot alternative in HDR (unlike LDR/MDR). Dwelling house MCU in this zone is Accepted where lot >= 400m2 and no secondary dwelling (Table 5.5.3; only overlay codes are requirements), so on such lots the zone code reaches a dwelling house / Class 10a building only as a QDC alternative provision via Table 1.5-1. On lots < 400m2 (or with a secondary dwelling <= 80m2) the dwelling house is accepted subject to requirements and the HDR zone code is a requirement. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_front_setback@2026-09-29$q$;
