SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.3.3 Table 6.2.3-1 RO1; Table 6.2.3-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Height | Setback | Front for covered car parking (excluding a basement) | all | 6m | Front (excluding covered car parking) | up to 23m | 4m | for that part exceeding 23m | 6m | Side and rear | up to 4.5m | 1.5m | for that part between 4.5m – 7.5m | 2m | for that part exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m | Between on site habitable buildings (where not attached) | Double the applicable side setback. | OR || Part B: AO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Height | Setback | Front for covered car parking (excluding a basement) | all | 6m | Front (excluding covered car parking) | up to 23m | 4m | for that part exceeding 23m | 6m | Side and rear | up to 4.5m | 1.5m | for that part between 4.5m – 7.5m | 2m | for that part exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m. | Between on site habitable buildings (where not attached) | Double the applicable side setback. | OR$q$, 'VERIFIED_VERBATIM', $q$ruleId 469 / 490$q$, NULL, $q$High density residential zone code (6.2.3)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/35/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_hdr_front_setback_covered_parking$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_front_setback_covered_parking", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "GARAGE.FRONTAGE", "title": "6.2.3.3 Table 6.2.3-1 RO1; Table 6.2.3-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": 6, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A"], "sources": [{"key": "gc_hdr_front_setback_covered_parking", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_setback_min_covered_car_parking\", \"operator\": \">=\", \"value\": 6, \"unit\": \"m\", \"conditions\": [\"all heights\"], \"exceptions\": [\"basement car parking excluded\", \"small lots: see gc_hdr_small_lot_covered_parking_setback\"], \"formula_text\": null}\nLot conditions (not encoded): Standard (non-small-lot) table\nStructure scope 'covered car parking (garage/carport), excluding a basement' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Row 'Front for covered car parking (excluding a basement) | all | 6m'. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
