INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_hdr_small_lot_front_setback@2026-09-29$q$, $q$QDC11.A1a.FRONTAGE_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.3.3 Table 6.2.3-1 RO1 (small lots); Table 6.2.3-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$OR Setbacks for Dwelling houses on small lots: | Setback | Minimum distances measured in metres (m) | Front | 4.5m to wall and balcony | Covered car parking: 2m behind front building line | Secondary frontage of corner lot | Front wall: 4m (not including projections up to 2m) | Covered car parking (not applicable to the rear lane access) | 1m behind front wall or balcony; and 6m from the frontage where vehicles access the lot. | Side and rear (not applicable to the secondary frontage of corner lots) | Height | Setback | up to 4.5m | 1m to wall and balcony 0.5m to outermost projection 0m to class 10 building and/or non-habitable room where: - located along a southern or western boundary; - a maximum length of 12m where no single part exceeds 6m in length; and - at least 1m separation from a habitable window of a neighbouring dwelling. | for that part between 4.5m – 7.5m | 1.5m to wall and balcony 1m to outermost projection | for that part exceeding 7.5m | 2m to wall and balcony 1.5 to outermost projection | Rear lane | 0.5m minimum 1m maximum for covered car parking || Part B: OR Setbacks for Dwelling houses on small lots: | Setback | Minimum distances measured in metres (m) | Front | 4.5m to wall and balcony | Secondary frontage of corner lot | 3m (not including projections up to 1m) | Covered car parking (not applicable to the rear lane access) | 1m behind front wall or balcony; and 6m from the frontage where vehicles access the lot. | Side and rear (not applicable to the secondary frontage of corner lots) | Height | Setback | up to 4.5m | 1m to wall and balcony 0.5m to outermost projection 0m to class 10 building and/or non-habitable room where: - located along a southern or western boundary; - a maximum length of 12m where no single part exceeds 6m in length; and - at least 1m separation from a habitable window of a neighbouring dwelling. | for that part between 4.5m – 7.5m | 1.5m to wall and balcony 1m to outermost projection | for that part exceeding 7.5m | 2m to wall and balcony 1.5m to outermost projection | Rear lane | 0.5m minimum 1m maximum for covered car parking$q$, 'VERIFIED_VERBATIM', $q$ruleId 469 / 490$q$, NULL, $q$High density residential zone code (6.2.3)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/35/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_hdr_small_lot_covered_parking_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_small_lot_covered_parking_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "GARAGE.FRONTAGE", "title": "6.2.3.3 Table 6.2.3-1 RO1 (small lots); Table 6.2.3-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": {"op": "unencoded", "text": "OR Setbacks for Dwelling houses on small lots: | Setback | Minimum distances measured in metres (m) | Front | 4.5m to wall and balcony | Covered car parking: 2m behind front building line | Secondary frontage of corner lot | Front wall: 4m (not including projections up to 2m) | Covered car parking (not applicable to the rear lane access) | 1m behind front wall or balcony; and 6m from the frontage where vehicles access the lot. | Side and rear (not applicable to the secondary frontage of corner lots) | Height | Setback | up to 4.5m | 1m to wall and balcony 0.5m to outermost projection 0m to class 10 building and/or non-habitable room where: - located along a southern or western boundary; - a maximum length of 12m where no single part exceeds 6m in length; and - at least 1m separation from a habitable window of a neighbouring dwelling. | for that part between 4.5m – 7.5m | 1.5m to wall and balcony 1m to outermost projection | for that part exceeding 7.5m | 2m to wall and balcony 1.5 to outermost projection | Rear lane | 0.5m minimum 1m maximum for covered car parking || Part B: OR Setbacks for Dwelling houses on small lots: | Setback | Minimum distances measured in metres (m) | Front | 4.5m to wall and balcony | Secondary frontage of corner lot | 3m (not including projections up to 1m) | Covered car parking (not applicable to the rear lane access) | 1m behind front wall or balcony; and 6m from the frontage where vehicles access the lot. | Side and rear (not applicable to the secondary frontage of corner lots) | Height | Setback | up to 4.5m | 1m to wall and balcony 0.5m to outermost projection 0m to class 10 building and/or non-habitable room where: - located along a southern or western boundary; - a maximum length of 12m where no single part exceeds 6m in length; and - at least 1m separation from a habitable window of a neighbouring dwelling. | for that part between 4.5m – 7.5m | 1.5m to wall and balcony 1m to outermost projection | for that part exceeding 7.5m | 2m to wall and balcony 1.5m to outermost projection | Rear lane | 0.5m minimum 1m maximum for covered car parking", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "gc_hdr_small_lot_covered_parking_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"covered_parking_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"1m behind front wall or balcony\", \"and 6m from the frontage where vehicles access the lot\", \"Part A RO1 only: 'Covered car parking: 2m behind front building line' (Front row)\"], \"exceptions\": [\"not applicable to the rear lane access\"], \"formula_text\": null}\nLot conditions (not encoded): small lot (< 400m2); not rear lane access\nStructure scope 'covered car parking (garage/carport) of Dwelling house on small lot' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: DISCREPANCY: Part A RO1 'Front' row has an extra line 'Covered car parking: 2m behind front building line' which is absent from Part B AO1. For accepted development subject to requirements both RO1 lines would apply (2m behind front building line AND 1m behind front wall or balcony, and 6m from vehicle-access frontage) - the stricter governs; confirm. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
