SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.3.3 Table 6.2.3-1 RO1 (small lots); Table 6.2.3-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Rear lane | 0.5m minimum 1m maximum for covered car parking$q$, 'VERIFIED_VERBATIM', $q$ruleId 469 / 490$q$, NULL, $q$High density residential zone code (6.2.3)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/35/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_hdr_small_lot_rear_lane$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_small_lot_rear_lane", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.REAR", "title": "6.2.3.3 Table 6.2.3-1 RO1 (small lots); Table 6.2.3-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": {"op": "unencoded", "text": "Rear lane | 0.5m minimum 1m maximum for covered car parking", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_1"], "sources": [{"key": "gc_hdr_small_lot_rear_lane", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"rear_lane_setback\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"0.5m minimum\", \"1m maximum for covered car parking\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): small lot with rear lane\nStructure scope 'dwelling house / covered car parking to rear lane' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Identical in RO1 and AO1 (unlike MDR, where RO1 reads '0.5m maximum'). Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_small_lot_rear_lane@2026-09-29$q$;
