SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.3.3 Table 6.2.3-1 RO2; Table 6.2.3-2 PO2/AO2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO2 Site cover does not exceed 50% for Dwelling houses on lots with areas equal to or greater than 400m2 and Dual occupancies. OR Site cover does not exceed 70% for Dwelling houses on lots less than 400m2. OR For all other uses, site cover does not exceed a cumulative total of : - 50% of net site area up to 8 storeys; - 40% of net site area from 9 to 15 storeys; and - 30% of net site area or 750m2 per building, whichever is the lesser, above 15 storeys. || Part B: PO2 Site cover: - is balanced between built form and green areas for landscaped private open space; - contributes to neighbourhood character and amenity; - promotes slender bulk form; - promotes an open, attractive and distinct skyline; and - facilitates small, fast moving shadows. | AO2 Site cover does not exceed 50% for Dwelling houses on lots with areas equal to or greater than 400m2 and Dual occupancies. OR Site cover does not exceed 70% for Dwelling houses on lots less than 400m2. OR For all other uses, site cover does not exceed a cumulative total of: - 50% of net site area up to 8 storeys; - 40% of net site area from 9 to 15 storeys; and - 30% of net site area or 750m2 per building, whichever is the lesser, above 15 storeys.$q$, 'VERIFIED_VERBATIM', $q$ruleId 482 / 508$q$, NULL, $q$High density residential zone code (6.2.3)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/35/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Site cover': portion of the site, as a percentage, covered by a building or structure measured to its outermost projection, excluding buildings/structures in a landscaped or open space area (e.g. gazebo, shade structure), a basement completely below ground used for car parking, eaves, and sun shades.$q$, $q$gc_hdr_site_cover$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_site_cover", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SITE_COVER", "title": "6.2.3.3 Table 6.2.3-1 RO2; Table 6.2.3-2 PO2/AO2", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": {"op": "unencoded", "text": "lot_area>=400 -> 50; lot_area<400 -> 70", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_hdr_site_cover", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"site_cover_max\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"%\", \"conditions\": [\"Dwelling house on lot >= 400m2: 50%\", \"Dwelling house on lot < 400m2: 70%\"], \"exceptions\": [\"other uses: cumulative 50%/40%/30% by storeys (not relevant to dwelling houses)\"], \"formula_text\": \"lot_area>=400 -> 50; lot_area<400 -> 70\"}\nLot conditions (not encoded): varies by lot area: lot >= 400m2 -> 50%; lot < 400m2 -> 70%\nStructure scope 'Dwelling houses (all buildings and structures counted per Site cover definition, incl. Class 10a)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Text identical in RO2 and AO2 apart from 'cumulative total of :' spacing. HDR small-lot site cover 70% (MDR 60%, LDR 50%). Table 1.5-1 (ruleId 2204): 'Alternatives to QDC site cover provisions | Relevant zone code or the following overlay code: - Ridges and significant hills protection overlay code ...' (Section 33(2) BA); overlay code prevails on inconsistency."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_site_cover@2026-09-29$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_hdr_site_cover@2026-09-29$q$, $q$QDC12.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_hdr_site_cover@2026-09-29$q$, $q$QDC11.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.3.3 Table 6.2.3-1 RO3; Table 6.2.3-2 PO3/AO3$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO3 Building height does not exceed 2 storeys and a maximum of 9m or that shown on the Building height overlay map. AND Structures do not exceed a height of 9m or that shown on the Building height overlay map. || Part B: PO3 Building height and structure height does not exceed 9m or that shown on the Building height overlay map. | AO3 No acceptable outcome provided.$q$, 'VERIFIED_VERBATIM', $q$ruleId 483 / 510$q$, NULL, $q$High density residential zone code (6.2.3)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/35/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Building height': vertical distance between ground level and the highest point on the roof (excluding aerial, chimney, flagpole, load-bearing antenna) or number of storeys above ground level. 'Partial third storey': GFA no greater than 50% of the storey immediately below.$q$, $q$gc_hdr_building_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_building_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "HEIGHT.BUILDING", "title": "6.2.3.3 Table 6.2.3-1 RO3; Table 6.2.3-2 PO3/AO3", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": {"op": "unencoded", "text": "max(9m & 2 storeys, Building height overlay map value) - 'or' reading assumed", "extracted_value": 9, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "gc_hdr_building_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"building_height_max\", \"operator\": \"conditional\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"RO3: 2 storeys and a maximum of 9m, or that shown on the Building height overlay map\", \"PO3: 9m or that shown on the Building height overlay map (no storey limit); AO3: no acceptable outcome\"], \"exceptions\": [], \"formula_text\": \"max(9m & 2 storeys, Building height overlay map value) - 'or' reading assumed\"}\nStructure scope 'buildings (incl. dwelling house and Class 10a buildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: 'or that shown on the Building height overlay map' - in HDR the overlay map usually designates much greater heights (storeys/metres, or 'HX'); the overlay value is not in this zone code and must be read from the Building height overlay map (the zone open-data layer's Building_height field returned only '2 (9m)' for HDR - see open_questions). No separate freestanding garage/carport height limit in HDR (LDR/MDR have 3.5m). MCU height triggers in Table 5.5.3 'do not apply to Dwelling houses, refer to Table 5.10.5 Dwelling house overlay'. Table 1.5-1 (ruleId 2205): 'Alternative to QDC building height provisions (performance criterion 4) | Relevant zone code | Section 32(b) BA and section 10(2)(b) BR'."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_building_height@2026-09-29$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_hdr_building_height@2026-09-29$q$, $q$QDC12.A4.BUILDING_HEIGHT$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_hdr_building_height@2026-09-29$q$, $q$QDC11.A4.BUILDING_HEIGHT$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.3.3 Table 6.2.3-1 RO3; Table 6.2.3-2 PO3/AO3$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO3 Building height does not exceed 2 storeys and a maximum of 9m or that shown on the Building height overlay map. AND Structures do not exceed a height of 9m or that shown on the Building height overlay map. || Part B: PO3 Building height and structure height does not exceed 9m or that shown on the Building height overlay map. | AO3 No acceptable outcome provided.$q$, 'VERIFIED_VERBATIM', $q$ruleId 483 / 510$q$, NULL, $q$High density residential zone code (6.2.3)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/35/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Building height': vertical distance between ground level and the highest point on the roof (excluding aerial, chimney, flagpole, load-bearing antenna) or number of storeys above ground level. 'Partial third storey': GFA no greater than 50% of the storey immediately below.$q$, $q$gc_hdr_structure_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_structure_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "HEIGHT.BUILDING", "title": "6.2.3.3 Table 6.2.3-1 RO3; Table 6.2.3-2 PO3/AO3", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 9, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["POOL"], "sources": [{"key": "gc_hdr_structure_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"structure_height_max\", \"operator\": \"<=\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"or that shown on the Building height overlay map\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'structures (non-building structures, e.g. pools, masts)' mapped by keyword to ['POOL']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: RO3 joins building and structure limits with 'AND'. Table 1.5-1 height alternative is to QDC P4 (building height); whether it extends to structures is unclear."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_structure_height@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.3.3 Table 6.2.3-1 RO4; Table 6.2.3-2 PO4$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO4 Density does not exceed that shown on the Residential density overlay map. OR Where not identified on the overlay map, density does not exceed one dwelling per 400m2. || Part B: PO4 For Dwelling houses density is one Dwelling house per lot. OR Density does not exceed that shown on the Residential density overlay map. OR Where not identified on the overlay map, density does not exceed one dwelling per 400m2. OR For Residential care facilities and Retirement facilities there is no performance outcome provided. OR For Rooming accommodation, accommodating more than four unrelated people, density does not exceed one bedroom per 133m2. | AO4$q$, 'VERIFIED_VERBATIM', $q$ruleId 484 / 513$q$, NULL, $q$High density residential zone code (6.2.3)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/35/0/false/08-Sep-2026/false$q$, NULL, $q$gc_hdr_density$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_density", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "OTHER", "title": "6.2.3.3 Table 6.2.3-1 RO4; Table 6.2.3-2 PO4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "<=", "value": 1, "unit": "dwelling house", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_hdr_density", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"dwelling_houses_per_lot\", \"operator\": \"<=\", \"value\": 1, \"unit\": \"dwelling house\", \"conditions\": [\"PO4: 'For Dwelling houses density is one Dwelling house per lot.'\", \"RO4: Residential density overlay map or one dwelling per 400m2 where not identified\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'residential use' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Context only."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_density@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$1.5 Table 1.5-1 (Alternatives to QDC boundary clearance provisions)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA$q$, 'VERIFIED_VERBATIM', $q$Table 1.5-1, ruleId 2203$q$, NULL, $q$Section 1.5 Building work regulated under the City Plan (Part 1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/63/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_hdr_pool_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_pool_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "POOL.SETBACK", "title": "1.5 Table 1.5-1 (Alternatives to QDC boundary clearance provisions)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_POOL_SETBACK", "operator": ">=", "value": {"op": "unencoded", "text": "Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA", "extracted_value": null, "extracted_operator": null}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["POOL"], "sources": [{"key": "gc_hdr_pool_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"pool_setback_min\", \"operator\": null, \"value\": null, \"unit\": \"m\", \"conditions\": [\"no HDR zone code pool setback; QDC/QHC setbacks apply unless in a Coastal erosion hazard 'Waterfront development control area'/'Foreshore seawall' area or a Road widening requirement area\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'swimming pools and other non-building structures' mapped by keyword to ['POOL']\nAlternative provision to QDC/QHC: NO\nResearcher notes: The HDR zone code contains no reference to swimming pools, sheds, garages, carports, outbuildings or 'domestic' (text search of all rules in section 35; only 'class 10' in the small-lot built-to-boundary cell). Under Table 1.5-1 the zone code is an alternative only for 'Buildings'; for 'Structures' only Coastal erosion hazard and Road widening overlay codes are alternatives. Pool = 'structure' classification is assumed - manual review."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_pool_setback@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$9.4.10.3 Table 9.4.10-1 RO1; Table 9.4.10-2 PO1/AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Where the street frontage is 10m or less: - a single storey dwelling is limited to a single car width opening (3m maximum); or - a two storey dwelling can have a double car width opening (6m maximum). || Part B: PO1 Covered car parking spaces and their vehicular access ways do not dominate the street front, and do not detract from pedestrian amenity and the established character of the neighbourhood streetscape. | AO1 Where the street frontage is 10m or less: - a single storey dwelling is limited to a single car width opening (3m maximum); or - a two storey dwelling can have a double car width opening (6m maximum).$q$, 'VERIFIED_VERBATIM', $q$ruleId 6073 / 6086$q$, NULL, $q$Small lot housing (infill focus) code (9.4.10)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/115/0/false/08-Sep-2026/false$q$, NULL, $q$gc_hdr_small_lot_garage_opening_width$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_small_lot_garage_opening_width", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "GARAGE.FRONTAGE", "title": "9.4.10.3 Table 9.4.10-1 RO1; Table 9.4.10-2 PO1/AO1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_GARAGE_CARPORT", "operator": ">=", "value": {"op": "unencoded", "text": "RO1 Where the street frontage is 10m or less: - a single storey dwelling is limited to a single car width opening (3m maximum); or - a two storey dwelling can have a double car width opening (6m maximum). || Part B: PO1 Covered car parking spaces and their vehicular access ways do not dominate the street front, and do not detract from pedestrian amenity and the established character of the neighbourhood streetscape. | AO1 Where the street frontage is 10m or less: - a single storey dwelling is limited to a single car width opening (3m maximum); or - a two storey dwelling can have a double car width opening (6m maximum).", "extracted_value": null, "extracted_operator": "conditional"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A"], "sources": [{"key": "gc_hdr_small_lot_garage_opening_width", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"garage_opening_width_max\", \"operator\": \"conditional\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"frontage <= 10m\", \"single storey: 3m\", \"two storey: 6m\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): small lot (< 400m2) with street frontage 10m or less\nStructure scope 'garage/carport opening (car parking)' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: NO\nResearcher notes: Small lot housing (infill focus) code is a listed requirement for 'Dwelling house if: - on a lot with an area less than 400m2; or - involving a secondary dwelling ...' (accepted subject to requirements) in Table 5.5.3 HDR. Code applies to 'material change of use for development for a Dwelling house on a small lot (a lot that has an area less than 400m2) where indicated within Part 5 Tables of assessment.' Same text as gc_small_lot_garage_opening_width (which lists only LDR/MDR). Not a Table 1.5-1 QDC alternative."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_small_lot_garage_opening_width@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$9.4.10.3 Table 9.4.10-1 RO14; Table 9.4.10-2 AO10$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO14 Within the front 3m of the primary frontage, development provides garden beds, planted with native species, along any side and front boundary, excluding driveway area, with a minimum width of 1m. OR The development has an existing operational works approval for landscape works. Note: This RO excludes frontages to rear lanes. || Part B: PO10 Landscaping is provided to: - soften the built form and hardstand areas; and - enhance the visual amenity of the area. | AO10 Within the front 3m of the primary frontage, development provides garden beds, planted with native species, along any side and front boundary, excluding driveway area, with a minimum width of 1m. OR The development has an existing Operational works approval for landscape works. Note: This AO excludes frontages to rear lanes.$q$, 'VERIFIED_VERBATIM', $q$ruleId 6079 / 6105$q$, NULL, $q$Small lot housing (infill focus) code (9.4.10)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/115/0/false/08-Sep-2026/false$q$, NULL, $q$gc_hdr_small_lot_landscaping_front$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_hdr_small_lot_landscaping_front", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "LANDSCAPE.OPEN_SPACE", "title": "9.4.10.3 Table 9.4.10-1 RO14; Table 9.4.10-2 AO10", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_LANDSCAPE", "operator": ">=", "value": 1, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:HIGH_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_hdr_small_lot_landscaping_front", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_garden_bed_width_min\", \"operator\": \">=\", \"value\": 1, \"unit\": \"m\", \"conditions\": [\"within front 3m of primary frontage\", \"along any side and front boundary excluding driveway area\"], \"exceptions\": [\"existing operational works approval for landscape works\", \"excludes frontages to rear lanes\"], \"formula_text\": null}\nLot conditions (not encoded): small lot (< 400m2)\nStructure scope 'front landscaping' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Requirement for a Dwelling house on a small lot in HDR (Table 5.5.3). Also RO3/AO3 private open space min 5m x 5m (not a siting number for Class 10a)."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_hdr_small_lot_landscaping_front@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.18.3 Table 6.2.18-1 RO1; Table 6.2.18-2 PO1/AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Setbacks are as follows | Setback | Minimum distances measured in metres (m) | Front | - if roadside stall: 0m - otherwise: 10m | Side and rear | 3m || Part B: PO1 Setbacks: - protect the amenity of adjoining uses; and - contribute to the semi-rural streetscape character. | AO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | - if roadside stall: 0m - otherwise: 10m | Side and rear | 3m$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.18-1 (Part A, ruleId 1889) and Table 6.2.18-2 (Part B, ruleId 1898)$q$, NULL, $q$Limited development (constrained land) zone code (6.2.18)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/20/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ld_front_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ld_front_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.FRONTAGE", "title": "6.2.18.3 Table 6.2.18-1 RO1; Table 6.2.18-2 PO1/AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 10, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LIMITED_DEVELOPMENT_CONSTRAINED_LAND"}], "subjects": ["ANY"], "sources": [{"key": "gc_ld_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_setback_min\", \"operator\": \">=\", \"value\": 10, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [\"roadside stall: 0m\"], \"formula_text\": null}\nStructure scope 'all buildings assessed against the zone code (no Class 10 / outbuilding distinction); roadside stall 0m' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: RO1 reads 'Setbacks are as follows' (no colon); AO1 'Setbacks are as follows:'. No secondary-frontage, small-lot, built-to-boundary or Class 10 provisions. Dwelling house MCU is accepted subject to requirements in this zone (Table 5.5.18) with the Limited development (constrained land) zone code as a requirement, so these numbers bind a dwelling house both as planning requirements and (via Table 1.5-1) as QDC alternative provisions for buildings. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ld_front_setback@2026-09-29$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ld_front_setback@2026-09-29$q$, $q$QDC12.A1a.ROAD_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ld_front_setback@2026-09-29$q$, $q$QDC11.A1a.FRONTAGE_SETBACK$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.18.3 Table 6.2.18-1 RO1; Table 6.2.18-2 PO1/AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO1 Setbacks are as follows | Setback | Minimum distances measured in metres (m) | Front | - if roadside stall: 0m - otherwise: 10m | Side and rear | 3m || Part B: PO1 Setbacks: - protect the amenity of adjoining uses; and - contribute to the semi-rural streetscape character. | AO1 Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | - if roadside stall: 0m - otherwise: 10m | Side and rear | 3m$q$, 'VERIFIED_VERBATIM', $q$ruleId 1889 / 1898$q$, NULL, $q$Limited development (constrained land) zone code (6.2.18)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/20/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ld_side_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ld_side_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.SIDE", "title": "6.2.18.3 Table 6.2.18-1 RO1; Table 6.2.18-2 PO1/AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_SIDE", "operator": ">=", "value": 3, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LIMITED_DEVELOPMENT_CONSTRAINED_LAND"}], "subjects": ["ANY"], "sources": [{"key": "gc_ld_side_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"side_setback_min\", \"operator\": \">=\", \"value\": 3, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'all buildings (no Class 10 / outbuilding distinction, no built-to-boundary allowance)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Single 3m 'Side and rear' value, not height-dependent. Dwelling house MCU is accepted subject to requirements in this zone (Table 5.5.18) with the Limited development (constrained land) zone code as a requirement, so these numbers bind a dwelling house both as planning requirements and (via Table 1.5-1) as QDC alternative provisions for buildings. Table 1.5-1 (s1.5, ruleId 2203, text unchanged in v14) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings such as sheds, garages, carports). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ld_side_setback@2026-09-29$q$;
