INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ld_rear_setback@2026-09-29$q$, $q$QDC11.A2a.SIDE_REAR_CLEARANCE$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.18.3 Table 6.2.18-1 RO2; Table 6.2.18-2 PO2/AO2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO2 Site cover for dwelling houses, on lots created by a residential reconfiguration of a lot approval, does not exceed 50%. OR Site cover does not exceed 10%. || Part B: PO2 Site cover: - reduces the dominance of buildings and structures; - addresses site constraints; - protects the semi-rural character; and - minimises the extent of impervious surfaces. | AO2 Site cover for dwelling houses, on lots created by a residential reconfiguration of a lot approval, does not exceed 50%. OR Site cover does not exceed 10%.$q$, 'VERIFIED_VERBATIM', $q$ruleId 1890 / 1901$q$, NULL, $q$Limited development (constrained land) zone code (6.2.18)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/20/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Site cover': portion of the site, as a percentage, covered by a building or structure measured to its outermost projection, excluding buildings/structures in a landscaped or open space area (e.g. gazebo, shade structure), a basement completely below ground used for car parking, eaves, and sun shades.$q$, $q$gc_ld_site_cover$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ld_site_cover", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SITE_COVER", "title": "6.2.18.3 Table 6.2.18-1 RO2; Table 6.2.18-2 PO2/AO2", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SITE_COVER", "operator": "<=", "value": {"op": "unencoded", "text": "lot created by residential ROL approval -> 50; else -> 10", "extracted_value": 10, "extracted_operator": "conditional"}, "unit": "%", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LIMITED_DEVELOPMENT_CONSTRAINED_LAND"}], "subjects": ["ANY"], "sources": [{"key": "gc_ld_site_cover", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"site_cover_max\", \"operator\": \"conditional\", \"value\": 10, \"unit\": \"%\", \"conditions\": [\"dwelling houses on lots created by a residential reconfiguration of a lot approval: 50%\", \"otherwise: 10%\"], \"exceptions\": [], \"formula_text\": \"lot created by residential ROL approval -> 50; else -> 10\"}\nLot conditions (not encoded): dwelling houses on lots created by a residential reconfiguration of a lot approval -> 50%; otherwise 10% (no lot-area threshold stated)\nStructure scope 'all buildings and structures counted in site cover (incl. sheds, garages, carports)' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Whether a lot was 'created by a residential reconfiguration of a lot approval' cannot be determined from zoning/cadastre alone - manual review / default to 10%. Table 1.5-1 (ruleId 2204): 'Alternatives to QDC site cover provisions | Relevant zone code or the following overlay code: - Ridges and significant hills protection overlay code ...' (Section 33(2) BA); overlay code prevails on inconsistency."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ld_site_cover@2026-09-29$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ld_site_cover@2026-09-29$q$, $q$QDC12.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ld_site_cover@2026-09-29$q$, $q$QDC11.A3.SITE_COVER$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.18.3 Table 6.2.18-1 RO3; Table 6.2.18-2 PO3/AO3.1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO3 Building height does not exceed 2 storeys and a maximum of 9m or that shown on the Building height overlay map. OR Structures do not exceed a height of 9m or that shown on the Building height overlay map. || Part B: PO3 Building height and structure height is low rise. | AO3.1 Building height does not exceed that shown on the Building height overlay map. OR Where not identified on the overlay map building height does not exceed: - 2 storeys with a maximum of 9m; or - a partial third storey if within 9m. AO3.2 Structures do not exceed a height of 9m or that shown on the Building height overlay map.$q$, 'VERIFIED_VERBATIM', $q$ruleId 1891 / 1903$q$, NULL, $q$Limited development (constrained land) zone code (6.2.18)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/20/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Building height': vertical distance between ground level and the highest point on the roof (excluding aerial, chimney, flagpole, load-bearing antenna) or number of storeys above ground level. 'Partial third storey': GFA no greater than 50% of the storey immediately below.$q$, $q$gc_ld_building_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ld_building_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "HEIGHT.BUILDING", "title": "6.2.18.3 Table 6.2.18-1 RO3; Table 6.2.18-2 PO3/AO3.1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 9, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LIMITED_DEVELOPMENT_CONSTRAINED_LAND"}], "subjects": ["CLASS_10A", "CLASS_1"], "sources": [{"key": "gc_ld_building_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"building_height_max\", \"operator\": \"<=\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"and not more than 2 storeys\", \"or the height shown on the Building height overlay map\", \"Part B AO3.1 also allows 'a partial third storey if within 9m' where not identified on the overlay map\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'buildings (incl. dwelling house and Class 10a buildings)' mapped by keyword to ['CLASS_10A', 'CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: No separate freestanding garage/carport height limit. MCU height triggers in Table 5.5.18 'do not apply to Dwelling houses, refer to Table 5.10.5 Dwelling house overlay'. Table 1.5-1 (ruleId 2205): 'Alternative to QDC building height provisions (performance criterion 4) | Relevant zone code | Section 32(b) BA and section 10(2)(b) BR'."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ld_building_height@2026-09-29$q$;
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ld_building_height@2026-09-29$q$, $q$QDC12.A4.BUILDING_HEIGHT$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ld_building_height@2026-09-29$q$, $q$QDC11.A4.BUILDING_HEIGHT$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.18.3 Table 6.2.18-1 RO3; Table 6.2.18-2 AO3.2$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO3 Building height does not exceed 2 storeys and a maximum of 9m or that shown on the Building height overlay map. OR Structures do not exceed a height of 9m or that shown on the Building height overlay map. || Part B: PO3 Building height and structure height is low rise. | AO3.1 Building height does not exceed that shown on the Building height overlay map. OR Where not identified on the overlay map building height does not exceed: - 2 storeys with a maximum of 9m; or - a partial third storey if within 9m. AO3.2 Structures do not exceed a height of 9m or that shown on the Building height overlay map.$q$, 'VERIFIED_VERBATIM', $q$ruleId 1891 / 1903$q$, NULL, $q$Limited development (constrained land) zone code (6.2.18)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/20/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Building height': vertical distance between ground level and the highest point on the roof (excluding aerial, chimney, flagpole, load-bearing antenna) or number of storeys above ground level. 'Partial third storey': GFA no greater than 50% of the storey immediately below.$q$, $q$gc_ld_structure_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ld_structure_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "HEIGHT.BUILDING", "title": "6.2.18.3 Table 6.2.18-1 RO3; Table 6.2.18-2 AO3.2", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_HEIGHT", "operator": "<=", "value": 9, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LIMITED_DEVELOPMENT_CONSTRAINED_LAND"}], "subjects": ["POOL"], "sources": [{"key": "gc_ld_structure_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"structure_height_max\", \"operator\": \"<=\", \"value\": 9, \"unit\": \"m\", \"conditions\": [\"or that shown on the Building height overlay map\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'structures (non-building structures, e.g. pools, masts)' mapped by keyword to ['POOL']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: RO3 joins the building and structure limits with 'OR' (HDR uses 'AND'; AO3.1/AO3.2 are separate) - drafting; read as cumulative. Whether Table 1.5-1 height alternative extends to structures is unclear."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ld_structure_height@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.18.3 Table 6.2.18-1 RO4; Table 6.2.18-2 PO4/AO4$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO4 Density is one dwelling house per lot. || Part B: PO4 Very low density reflects the semi-rural character of the zone. | AO4 Density is one dwelling house per lot.$q$, 'VERIFIED_VERBATIM', $q$ruleId 1892 / 1906$q$, NULL, $q$Limited development (constrained land) zone code (6.2.18)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/20/0/false/08-Sep-2026/false$q$, NULL, $q$gc_ld_density$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ld_density", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "OTHER", "title": "6.2.18.3 Table 6.2.18-1 RO4; Table 6.2.18-2 PO4/AO4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OTHER", "operator": "<=", "value": 1, "unit": "dwelling house", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LIMITED_DEVELOPMENT_CONSTRAINED_LAND"}], "subjects": ["ANY"], "sources": [{"key": "gc_ld_density", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"dwelling_houses_per_lot\", \"operator\": \"<=\", \"value\": 1, \"unit\": \"dwelling house\", \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'residential use' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: NO\nResearcher notes: Context only."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ld_density@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$1.5 Table 1.5-1 (Alternatives to QDC boundary clearance provisions)$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA$q$, 'VERIFIED_VERBATIM', $q$Table 1.5-1, ruleId 2203$q$, NULL, $q$Section 1.5 Building work regulated under the City Plan (Part 1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/63/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ld_pool_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ld_pool_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "POOL.SETBACK", "title": "1.5 Table 1.5-1 (Alternatives to QDC boundary clearance provisions)", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_POOL_SETBACK", "operator": ">=", "value": {"op": "unencoded", "text": "Alternatives to QDC boundary clearance provisions | Buildings: Relevant zone code, and the following overlay codes: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ on the Coastal erosion hazard overlay map - Mudgeeraba Village character overlay code, if within the ‘Mudgeeraba Village character’ area on the Mudgeeraba Village character overlay map - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map - Water resource catchment overlay code, if in the ‘Water supply buffer area’ on the Water catchments and dual supply system area overlay map Note: In the event of an inconsistency between the zone code and an overlay code, the overlay code prevails. Structures: - Coastal erosion hazard overlay code, if in a ‘Waterfront development control area’ or ‘Foreshore seawall’ area on the Coastal erosion hazard overlay map. - AO1 and PO1 of the Road widening overlay code, if on a lot affected by a ‘Road widening requirement area’ as identified on the Road widening overlay map Note: QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes. | Section 33(2) BA", "extracted_value": null, "extracted_operator": null}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LIMITED_DEVELOPMENT_CONSTRAINED_LAND"}], "subjects": ["POOL"], "sources": [{"key": "gc_ld_pool_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"pool_setback_min\", \"operator\": null, \"value\": null, \"unit\": \"m\", \"conditions\": [\"no Limited development zone code pool setback; QDC/QHC setbacks apply unless in a Coastal erosion hazard 'Waterfront development control area'/'Foreshore seawall' area or a Road widening requirement area\"], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'swimming pools and other non-building structures' mapped by keyword to ['POOL']\nAlternative provision to QDC/QHC: NO\nResearcher notes: The Limited development (constrained land) zone code contains no reference to swimming pools, sheds, garages, carports, outbuildings or Class 10 (text search of all rules in section 20). If treated as a planning requirement, RO1 3m side/rear (which speaks of 'Setbacks' generally) might be read as applying to a pool under the scheme's Setback definition ('building or structure') - manual review. Pool = 'structure' classification for Table 1.5-1 is assumed."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ld_pool_setback@2026-09-29$q$;

INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$QHC: Version 14 has no reference to the Queensland Housing Code. Under Building Regulation 2021 s106 transition (secondary source: thegoodbuilder.com.au), QDC MP1.1/1.2 'continue to apply' for a council until it amends its scheme or 1 Sept 2029 - confirm how Gold Coast's existing QDC alternative provisions interact with the QHC during transition.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$LDR/MDR standard (non-small-lot) setback table gives no built-to-boundary or reduced setback for Class 10a buildings - confirm whether certifiers apply zone 1.5m side/rear to sheds/garages/carports on >=400m2 lots (Table 1.5-1 says zone code is the alternative for 'Buildings').$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Whether patios/pergolas/decks/pools are 'buildings' (zone code alternative applies) or 'structures' (QDC/QHC applies except coastal/road widening overlays) - classification needed per Table 1.5-1.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$LDR 'Height' column in side/rear setback (whole building height vs part height) and base for the >7.5m increment.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$MDR Part A RO1 rear lane '0.5m maximum' vs Part B AO1 '0.5m minimum' inconsistency.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Table 5.5.1(1) Large lot precinct: dwelling house accepted if lot >=400m2 'or' not involving secondary dwelling (vs 'and' elsewhere).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Section 1.5 cross-references 'section 1.6(4)' and 'Building Regulation 2006' - stale references.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Building height overlay map, Dwelling house overlay map, Residential density and overlay extents are spatial - need GIS (ePlan api/l/rev/gis endpoints) to apply per lot.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$High density residential zone, Emerging community, Mixed use zone dwelling house provisions not extracted.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Water resource catchment Table 8.2.19-2 separation distance values not extracted.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Bushfire hazard overlay code: no setback/separation numbers found by text search for 'setback'/'separation' - not reviewed in depth.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Rural zone code has NO site cover provision. Table 1.5-1 names the 'Relevant zone code' as the site-cover alternative; with nothing in the Rural code, QDC/QHC site cover presumably applies - confirm with a certifier.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Corner / dual-frontage lots: both codes give only 'Front' (Rural 10m; EC 10m or 6m) and 'Side and rear'; no secondary frontage rule. Whether every road boundary is a 'Front' (Sch 1 'Frontage' = boundary between a site and a road) is unresolved.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$No Class 10a-specific allowances (built-to-boundary, outbuilding floor-area limit, garage/carport height) exist in either zone code. If sheds/garages/carports are 'buildings' under Table 1.5-1, the zone setbacks (Rural 10m/6m; EC 10m/6m or 6m/1.5m+ tiers) displace the QDC MP1.2 Class 10a boundary allowances. Confirm certifier practice.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Pools: not mentioned in either zone code. Assumed to be 'structures' -> QDC/QHC setbacks (plus pool safety) unless the Coastal erosion hazard or Road widening overlay applies.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Emerging community: 'lot created through a residential subdivision approval' and 'unless the earlier approval specifies otherwise' cannot be evaluated from zoning alone - needs development approval / plan of development data. Default values are severe (10m front, 6m side/rear, 5% site cover).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Emerging community height: RO3/AO3 defer to the Building height overlay map where it shows a value; needs GIS lookup.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Emerging community: Dwelling house with a secondary dwelling > 80m2 GFA is not listed in Table 5.5.15 - presumed impact assessable under s5.3.2 (not verified with council).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Rural Table 5.5.20 density trigger row reads 'For all uses other than: Dwelling; or Caretaker's accommodation' while Table 5.5.20(1) reads 'Dwelling house' - probable drafting slip, no siting effect.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Rural RO2 (accepted subject to requirements) omits the AO2.1 'partial third storey if within 9m' alternative; Rural structures have no height limit at all.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Emerging community AO1 'up to 4.5' lacks the unit (RO1 has 4.5m) - typographical.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$QHC interaction (Building Regulation 2021 s106 transition) unresolved - v14 still references QDC MP1.1/1.2 only.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Whether the Part A (RO) or Part B (AO) wording is the 'Relevant zone code' alternative under Table 1.5-1 is not stated; numbers are identical in both parts for these two zones.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$HDR small-lot table: Part A RO1 and Part B AO1 differ - RO1 secondary frontage 'Front wall: 4m (not including projections up to 2m)' vs AO1 '3m (not including projections up to 1m)'; RO1 Front row has an extra 'Covered car parking: 2m behind front building line' absent from AO1. Which governs as the QDC alternative provision (RO1 assumed)?$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$HDR building height 'or that shown on the Building height overlay map': the overlay height (often high-rise in HDR) must come from the Building height overlay map; the Version 13 open-data Zone layer field Building_height returns only '2 (9m)' for every HDR polygon, which looks like a default rather than the overlay value - source the Building height overlay layer before using >9m in HDR.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$HDR has no freestanding garage/carport height limit (LDR/MDR: 3.5m) and no rear-lot setback alternative - confirmed by text search; engine should not carry LDR/MDR values over.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$HDR standard (>=400m2) table: no built-to-boundary/reduced setback for Class 10a buildings - Class 10a on lots >= 400m2 get 1.5m side/rear (and 4m front, 6m for covered car parking) as the QDC alternative per Table 1.5-1 'Buildings: Relevant zone code'.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$LD site cover: 50% only for 'dwelling houses, on lots created by a residential reconfiguration of a lot approval', otherwise 10% - lot origin is not derivable from zone data; default 10% unless confirmed.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$LD MCU Dwelling house condition is drafted 'if: - not involving a secondary dwelling; or - not involving a secondary dwelling with a GFA exceeding 80m2' - read as: no secondary dwelling, or secondary dwelling <= 80m2. A dwelling house with a secondary dwelling > 80m2 is not described and falls to impact assessment (inferred).$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Pools: neither zone code mentions pools; Table 1.5-1 gives zone code alternatives only for 'Buildings', so pools (assumed 'structures') use QDC/QHC setbacks unless in Coastal erosion hazard / Road widening overlay areas. In LD, where the zone code is a planning requirement for the dwelling house MCU, whether the 3m side/rear 'Setbacks' RO1 also captures a pool (Setback definition covers 'building or structure') is unresolved.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Existing gc_small_lot_* records (garage opening width, front landscaping) list only LDR/MDR zones, but Table 5.5.3 also makes the Small lot housing (infill focus) code a requirement for HDR dwelling houses on lots < 400m2 - added as gc_hdr_small_lot_* here.$q$);
INSERT INTO open_issues (lg_id, instrument_id, severity, description) VALUES ($q$GOLD_COAST$q$, $q$CGC_CITY_PLAN$q$, 'MEDIUM', $q$Zone open data is 'City_Plan_Version_13_Open_Data' - precinct values ('None' for both zones) are from Version 13 data; no HDR/LD precinct exists in the v14 ePlan TOC either.$q$);
